-- AgroBusiness Malawi: community price location taxonomy
-- Sources researched 2026-08-15: ADMARC commercial markets; Lilongwe City/NSO/JICA;
-- Blantyre Water Board/City Council; Mzuzu City/NSO; Zomba City Council.
-- Run once after the existing crowdsourced_prices table exists.

START TRANSACTION;

CREATE TABLE IF NOT EXISTS price_markets (
  id INT UNSIGNED NOT NULL AUTO_INCREMENT,
  district_id INT NOT NULL,
  name VARCHAR(180) NOT NULL,
  active TINYINT(1) NOT NULL DEFAULT 1,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_price_market (district_id,name),
  KEY idx_price_market_district (district_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS price_areas (
  id INT UNSIGNED NOT NULL AUTO_INCREMENT,
  district_id INT NOT NULL,
  name VARCHAR(180) NOT NULL,
  city_name VARCHAR(120) NULL,
  active TINYINT(1) NOT NULL DEFAULT 1,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_price_area (district_id,name),
  KEY idx_price_area_district (district_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

ALTER TABLE crowdsourced_prices
  MODIFY district_id INT NULL,
  ADD COLUMN market_id INT UNSIGNED NULL AFTER district_id,
  ADD COLUMN area_id INT UNSIGNED NULL AFTER market_id,
  ADD COLUMN email VARCHAR(255) NULL AFTER area_id,
  ADD KEY idx_cp_market (market_id),
  ADD KEY idx_cp_area (area_id),
  ADD KEY idx_cp_email (email);

